import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"25、【無妄】 震下乾上","description":"子夏易傳 - 25、【無妄】 震下乾上","frontmatter":{"title":"25、【無妄】 震下乾上","description":"子夏易傳 - 25、【無妄】 震下乾上"},"headers":[],"relativePath":"classics/zixia/027.md","filePath":"classics/zixia/027.md"}'),i={name:"classics/zixia/027.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_25、【無妄】-震下乾上" tabindex="-1">25、【無妄】 震下乾上 <a class="header-anchor" href="#_25、【無妄】-震下乾上" aria-label="Permalink to “25、【無妄】 震下乾上”">​</a></h1><p>卦辭：無妄，元亨利貞，其匪正有眚，不利有攸往。</p><p>彖曰：無妄，剛自外來而，為主於內，動而健，剛中而應，大亨以正天之命也。其匪正有眚，不利有攸往，無妄之往，何之矣。天命不祐行矣哉。</p><p>子夏：天徳在上，求賢以治時，在乎前也。剛自外來而踐其初，而為治主於內，其體動而健上，剛中而下柔，應之上下一徳理，無違者非大亨，以正乎此天之命。上使之行，下得陳其力也。其匪正而往，非上之至違於天，　背於時也。行矣哉，不可行者也。</p><p>象曰：天下雷行，物與無妄。先王以茂對時育萬物。</p><p>子夏：天下雷行，雷動而震物，得其生，自正其命相與不妄矣。故先王求有徳，以茂其治，對時而養萬物。</p><p>初九，無妄，往吉。</p><p>象曰：無妄之往，得志也。</p><p>子夏：以剛而來居內卦之下。志行其正以輔於乾，為佐治之主，往來必得其志也。</p><p>六二，不耕穫，不菑畬，則利有攸往。</p><p>象曰：不耕穫，未富也。</p><p>子夏：剛正而在乎前，柔守位而上，應也。其可妄乎。不合初以首事，不與鄰以謀富，故不耕菑穫畬而已矣。承令而行，則利其往也。</p><p>六三，無妄之災，或繫之牛行人之得，邑人之災。</p><p>象曰：行人得牛，邑人災也，陰妄居陽災之道也。</p><p>子夏：牛者，陰之類也。非所履而履之，繫之者也。四近而得之，非其本合，行人之得也，本應於上。邑人之謂也。上道窮而爭合，故受之災，以其行人得牛，而致其忿也。</p><p>九四，可貞無咎。</p><p>象曰：可貞無咎，固有之也。</p><p>子夏：係於三，咎也。居尊守卑，正以承上，得民不以為私，猶可固其所有，而免於咎。</p><p>九五，無妄之疾，勿藥有喜。</p><p>象曰：無妄之藥，不可試也。</p><p>子夏：剛自外來，為主於內，動而得民，往而獲志，道既盛矣，則疑疾之也。夫以剛動，強志在，於正攻之，則反害從之，則成功。故藥之増剝待之，終吉。</p><p>上九，無妄，行有眚，無攸利。</p><p>象曰：無妄之行，窮之災也。</p><p>子夏：乘於剛，上於尊而又爭。應窮高極危，妄之甚也。復何往哉，無所利也。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
